export function applySourceValues(base,values){const out=structuredClone(base);for(const [path,value] of Object.entries(values??{})){const parts=path.split('.');if(parts.some(p=>['__proto__','prototype','constructor'].includes(p)))throw Error('Unsafe data path');let target=out;for(const p of parts.slice(0,-1)){if(!target||!Object.hasOwn(target,p))throw Error('Unknown source path');target=target[p];}const last=parts.at(-1);if(!target||!Object.hasOwn(target,last)||typeof target[last]!==typeof value||!['number','string'].includes(typeof value))throw Error('Source data type changed');target[last]=value;}return out;}
export function guideDerived(key,data){if(key==='goldrush')for(const tile of data.tiles)tile.perHour=tile.perMinute*60;return data;}
export function validateEditorValues(record,values){for(const [path,s] of Object.entries(record.schema)){const v=values[path];if(s.type==='number'){if(!Number.isFinite(v)||!Number.isInteger(v)||v<(s.min??0)||v>(s.max??1e9))throw Error('Check '+s.label);}else{if(typeof v!=='string'||v.length>(s.maxLength??500))throw Error('Check '+s.label);if(s.options&&!s.options.includes(v))throw Error('Choose '+s.label);if(s.format==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||new Date(v+'T00:00:00Z').toISOString().slice(0,10)!==v))throw Error('Enter a valid date for '+s.label);if(s.format==='url'&&!(path==='extraUrl'&&v==='')&&!/^https:\/\/[^\s]+$/i.test(v))throw Error('Use an HTTPS URL for '+s.label);}}const groups=new Map();for(const [path,value]of Object.entries(values)){const m=/^(rewards|chests|teamMilestones)\.(\d+)\.(threshold|points)$/.exec(path);if(m){if(!groups.has(m[1]))groups.set(m[1],[]);groups.get(m[1]).push([Number(m[2]),value]);}}for(const rows of groups.values()){rows.sort((a,b)=>a[0]-b[0]);if(rows.some((r,i)=>i&&r[1]<=rows[i-1][1]))throw Error('Milestone thresholds must increase in row order');}if(record.key==='schedule'){for(const [kind,count]of [['regular',5],['pvp',4]]){const names=Array.from({length:count},(_,i)=>values[`events.${kind}.events.${i}`]);if(new Set(names).size!==count)throw Error('Each event must appear once in the rotation');}if(values['horde.rest_seconds']>=values['horde.cycle_seconds'])throw Error('Horde rest must be shorter than its full cycle');}if(['footer','announcement'].includes(record.key)&&Boolean(values.extraLabel)!==Boolean(values.extraUrl))throw Error('Add both the optional link text and URL');return values;}
